import{describe,it,expect}from"vitest";import{railwayMilestones,railwayEras,getMilestoneById,getMilestonesByEra,filterMilestones,calculateTrainTrackPosition}from"../../frontend/railways-timeline/railways-timeline.js";const REQUIRED_MILESTONE_FIELDS=["id","year","date","title","route","era","description","significance","neutralContext","techSpecs","icon","trainIcon","trackPositionPercent"];describe("History of Indian Railways Milestones Integrity",()=>{it("contains at least 8 verified historical milestones (contains 10)",()=>{expect(railwayMilestones.length).toBeGreaterThanOrEqual(8)}),it("milestones are strictly sorted in chronological order",()=>{for(let e=0;e<railwayMilestones.length-1;e++)expect(railwayMilestones[e].year).toBeLessThanOrEqual(railwayMilestones[e+1].year)}),it("every milestone contains all required fields with non-empty values",()=>{railwayMilestones.forEach((e,t)=>{REQUIRED_MILESTONE_FIELDS.forEach(i=>{expect(e,`Milestone at index ${t} missing field ${i}`).toHaveProperty(i),"year"===i||"trackPositionPercent"===i?expect(typeof e[i]).toBe("number"):"techSpecs"===i?expect(typeof e.techSpecs).toBe("object"):(expect(typeof e[i]).toBe("string"),expect(e[i].trim().length).toBeGreaterThan(0))})})}),it("provides neutral & factual historical framing for colonial-era milestones",()=>{const e=railwayMilestones.filter(e=>e.era.includes("Colonial"));expect(e.length).toBeGreaterThanOrEqual(4),e.forEach(e=>{expect(e.neutralContext).toBeDefined(),expect(e.neutralContext.length).toBeGreaterThan(20)})}),it("all milestone IDs are unique",()=>{const e=railwayMilestones.map(e=>e.id);expect(new Set(e).size).toBe(e.length)})}),describe("Train Track Position Math Calculation",()=>{it("calculates 0% for first milestone and 100% for last milestone",()=>{expect(calculateTrainTrackPosition(0,10)).toBe(0),expect(calculateTrainTrackPosition(9,10)).toBe(100)}),it("calculates correct mid-point position percentage",()=>{expect(calculateTrainTrackPosition(4,9)).toBe(50)}),it("handles edge cases gracefully (e.g. single item or negative index)",()=>{expect(calculateTrainTrackPosition(0,1)).toBe(0),expect(calculateTrainTrackPosition(-5,10)).toBe(0),expect(calculateTrainTrackPosition(99,10)).toBe(100)})}),describe("Milestone Query Helpers",()=>{it("retrieves milestone by ID or Year",()=>{const e=getMilestoneById("m-1853");expect(e).toBeDefined(),expect(e.title).toContain("First Passenger Train");const t=getMilestoneById("2019");expect(t).toBeDefined(),expect(t.title).toContain("Vande Bharat")}),it("retrieves milestones filtered by Era",()=>{const e=getMilestonesByEra("Colonial Expansion");expect(e.length).toBeGreaterThanOrEqual(4);const t=getMilestonesByEra("Modernization");expect(t.length).toBeGreaterThanOrEqual(2)}),it("filters milestones by search query (e.g. Bori Bunder or Electric)",()=>{const e=filterMilestones("Bori Bunder");expect(e.length).toBeGreaterThan(0),expect(e[0].year).toBe(1853);const t=filterMilestones("Electric");expect(t.length).toBeGreaterThan(0)}),it("returns empty array when query matches nothing",()=>{const e=filterMilestones("UnknownTrainQueryXYZ");expect(e).toEqual([])})});